-- Paket ABT "abt-tinjau-31okt" (31 Okt 2026): jawaban pengguna G6 (banding UU 20/1947, 288 = 1875 KUHPerdata, 718 = 390 HIR, 144 (1) = 120 HIR, tenggang verzet ayat (2), RBg baku, butir "-"). Hanya derry_briantono.
-- PRASYARAT "A|B|C|D|E": A = 11896-11899 / 12000-12019 berisi lain (0) | B = variabel baru persis (0/17) | C = kueri lama persis dasar (16/0) | D = kueri lama sudah isi baru (0/16) | E = #11850# dan #11861# paket hir-rbg ada (2)
SELECT CONCAT_WS('|',
 (SELECT COUNT(*) FROM abt_variabel v WHERE (v.no_var BETWEEN 11896 AND 11899 OR v.no_var BETWEEN 12000 AND 12019) AND NOT EXISTS (SELECT 1 FROM (SELECT 11896 AS n, 'ae1de44ff962d00feb6ab0305c0b299b' AS h UNION ALL SELECT 11897 AS n, '5e93551746a4095c7f0fdd07618b42b6' AS h UNION ALL SELECT 11898 AS n, '51f48b6a4d512fb8231de3b9b151d0f5' AS h UNION ALL SELECT 11899 AS n, '2303d4c9eea349eb7bee0be247978c2f' AS h UNION ALL SELECT 12000 AS n, '3c5c28c407f8543fe8f5e2c71fa27270' AS h UNION ALL SELECT 12001 AS n, '37973091e19590d1044d07d74cd18c1f' AS h UNION ALL SELECT 12002 AS n, '5e53c28538970d2e7be0c87b5a4b3010' AS h UNION ALL SELECT 12003 AS n, '070b09d1fe17627dfa0cf2e2ba121583' AS h UNION ALL SELECT 12004 AS n, '25e5eaa12637a263e1346d06c29b9536' AS h UNION ALL SELECT 12005 AS n, '3de1ed80aae67ff5bdcf74f73fcede3e' AS h UNION ALL SELECT 12006 AS n, '272655f704e7d3aff0df7d417dc98c63' AS h UNION ALL SELECT 12007 AS n, '5aa3c0e262dc51b0def7711862521525' AS h UNION ALL SELECT 12008 AS n, 'f6df31b643241b1928cb5a3f5aa4c406' AS h UNION ALL SELECT 12009 AS n, '21fb17b5d9420a5e1281ab75cefa3022' AS h UNION ALL SELECT 12010 AS n, '76091294967098ada50989cd56308854' AS h UNION ALL SELECT 12011 AS n, 'e1fddfb6d41a89116659a34b4c23cd75' AS h UNION ALL SELECT 12012 AS n, 'e5fd8ade98d55cff2b2fc88f2aaaf099' AS h) p WHERE p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))))),
